// ==========================================
// EXTRA-QUESTION HELPERS — UNITS 9–12 ONLY (addQuestions912)
// Each blueprint lesson builds 1 teach card + 7 questions. These helpers
// wrap the built lesson and insert 3 extra questions (after s2 / s6 / s8)
// so every stage ends up with 1 teach card + exactly 10 questions.
// Compact factories mirror the exact content shapes buildRichLessonFromBlueprint
// produces, so audit-lessons.ts passes: tiles (not wordTiles) for
// sentence_builder, acceptedAnswers/acceptedVariants include correctAnswer,
// declension steps carry both canonical field pairs.
// Naming is 912-suffixed so it cannot collide with other units' helpers.
// ==========================================

type LText912 = { ru: string; en: string; ar: string; fr: string };
const L912 = (ru: string, en: string, ar: string, fr: string): LText912 => ({ ru, en, ar, fr });
const stripStress912 = (s: string): string => s.replace(/\u0301/g, '');
const cleanUpper912 = (s: string): string =>
  stripStress912(s).replace(/[^а-яёА-ЯЁ]/g, '').toUpperCase();

function mk912(key: string, type: LessonStep['type'], content: LessonStep['content']): LessonStep {
  // key is '<lessonId>-x<n>'; lessonId is everything before '-x<n>'.
  const lessonId = key.slice(0, key.lastIndexOf('-x'));
  return { id: key, lessonId, orderIndex: 0, type, content };
}

function pic912(
  key: string,
  icon: string,
  answer: string,
  options: string[],
  tr: LText912,
  slug: string,
): LessonStep {
  return mk912(key, 'picture_word', {
    iconKey: icon,
    audioText: stripStress912(answer),
    audioSlug: slug,
    options,
    correctAnswer: answer,
    translation: tr,
    hint: {
      ru: `Правильный ответ: ${answer}`,
      en: `Listen carefully for "${answer}" (${tr.en}).`,
      ar: `استمع جيداً للكلمة الصحيحة: ${answer}.`,
      fr: `Écoutez attentivement « ${answer} ».`,
    },
  });
}

function fill912(
  key: string,
  before: string,
  after: string,
  answer: string,
  options: string[],
  tr: LText912,
  slug: string,
): LessonStep {
  return mk912(key, 'fill_blank', {
    sentenceBefore: before,
    sentenceAfter: after,
    audioText: stripStress912(`${before}${answer}${after}`),
    audioSlug: slug,
    options,
    acceptedAnswers: [answer],
    correctAnswer: answer,
    translation: tr,
    hint: {
      ru: `Нужная форма: ${answer}`,
      en: `Choose the grammatically matching form: ${answer}`,
      ar: `الصيغة الصحيحة هي: ${answer}`,
      fr: `La forme correcte est : ${answer}`,
    },
  });
}

function decl912(
  key: string,
  before: string,
  after: string,
  base: string,
  caseCode: 'nom' | 'gen' | 'dat' | 'acc' | 'ins' | 'prep',
  answer: string,
  options: string[],
  tr: LText912,
  slug: string,
): LessonStep {
  return mk912(key, 'case_declension', {
    sentenceBefore: before,
    sentenceAfter: after,
    baseNounWithStress: base,
    requiredCase: caseCode,
    baseNounStressed: base,
    targetCaseCode: caseCode,
    contextBefore: before,
    contextAfter: after,
    audioText: stripStress912(`${before} ${answer} ${after}`),
    audioSlug: slug,
    options,
    acceptedAnswers: [answer],
    correctAnswer: answer,
    translation: tr,
    hint: {
      ru: `Поставьте слово «${base}» в форму «${answer}».`,
      en: `Decline "${base}" to "${answer}".`,
      ar: `حوّل الكلمة «${base}» إلى الصيغة «${answer}».`,
      fr: `Déclinez « ${base} » en « ${answer} ».`,
    },
  });
}

function sent912(
  key: string,
  tiles: string[],
  accepted: string[][],
  prompt: LText912,
  slug: string,
): LessonStep {
  const answer = accepted[0].join(' ');
  return mk912(key, 'sentence_builder', {
    audioText: stripStress912(answer),
    audioSlug: slug,
    promptText: prompt,
    tiles,
    acceptedOrders: accepted,
    correctAnswer: answer,
    hint: {
      ru: `Правильный порядок: ${answer}`,
      en: `Correct order starts with: ${accepted[0][0]}`,
      ar: `الترتيب الصحيح يبدأ بـ: ${accepted[0][0]}`,
      fr: `L’ordre correct commence par : ${accepted[0][0]}`,
    },
  });
}

function type912(
  key: string,
  mode: 'translation_typing' | 'listening_dictation',
  answer: string,
  prompt: LText912,
  tr: LText912,
  slug: string,
): LessonStep {
  const clean = stripStress912(answer);
  const upper = cleanUpper912(answer);
  return mk912(key, mode, {
    audioText: clean,
    audioSlug: slug,
    sourcePrompt: prompt,
    acceptedAnswers: [answer, clean],
    acceptedVariants: [answer, clean],
    correctAnswer: answer,
    translation: tr,
    targetWordWithStress: answer,
    targetCleanWord: upper,
    tiles: upper.split(''),
    hint: {
      ru: `Введите слово: ${answer}`,
      en: `Type in Russian: ${answer}`,
      ar: `اكتب بالروسية: ${answer}`,
      fr: `Tapez en russe : ${answer}`,
    },
  });
}

function addQuestions912(
  lesson: CurriculumLesson,
  inserts: { after: string; step: LessonStep }[],
): CurriculumLesson {
  const steps = [...lesson.steps];
  for (const ins of inserts) {
    const anchor = `${lesson.id}-${ins.after}`;
    const idx = steps.findIndex((s) => s.id === anchor);
    if (idx === -1) throw new Error(`[addQuestions912] anchor ${anchor} not found in ${lesson.id}`);
    steps.splice(idx + 1, 0, ins.step);
  }
  steps.forEach((s, i) => {
    s.orderIndex = i + 1;
  });
  return { ...lesson, steps, estimatedMinutes: 8 };
}

